//! Integration tests for rugix-pki using OpenSSL to generate test certificates.

use std::process::Command;
use std::time::Duration;
use std::time::SystemTime;

use cms::content_info::ContentInfo;
use cms::signed_data::SignedData;
use der::Decode;
use der::Encode;
use der::asn1::Any;
use der::asn1::OctetString;
use rugix_pki::CmsSigner;
use rugix_pki::CmsSignerBuilder;
use rugix_pki::CmsVerifier;
use rugix_pki::RsaHashAlgorithm;
use rugix_pki::RsaSignatureMode;
use rugix_pki::verify_cms_with_certificate;

/// Test certificates and keys generated by OpenSSL.
struct TestPki {
    root_cert_pem: Vec<u8>,
    signer_cert_pem: Vec<u8>,
    signer_key_pem: Vec<u8>,
    other_root_cert_pem: Vec<u8>,
    temp_dir: tempfile::TempDir,
}

impl TestPki {
    fn new() -> Self {
        let temp_dir = tempfile::tempdir().expect("failed to create temp dir");
        let dir = temp_dir.path();

        let ee_ext_path = dir.join("ee.ext");
        std::fs::write(
            &ee_ext_path,
            "basicConstraints=critical,CA:FALSE\nkeyUsage=digitalSignature\n",
        )
        .expect("failed to write EE extensions");

        let root_key_path = dir.join("root.key");
        let root_cert_path = dir.join("root.crt");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&root_key_path)
            .status()
            .expect("failed to generate root key");
        assert!(status.success(), "failed to generate root key");

        let status = Command::new("openssl")
            .args(["req", "-x509", "-new", "-key"])
            .arg(&root_key_path)
            .args(["-out"])
            .arg(&root_cert_path)
            .args(["-days", "3650", "-subj", "/CN=Test Root CA"])
            .args(["-addext", "basicConstraints=critical,CA:TRUE"])
            .args(["-addext", "keyUsage=keyCertSign,cRLSign"])
            .status()
            .expect("failed to generate root cert");
        assert!(status.success(), "failed to generate root cert");

        let signer_key_path = dir.join("signer.key");
        let signer_csr_path = dir.join("signer.csr");
        let signer_cert_path = dir.join("signer.crt");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&signer_key_path)
            .status()
            .expect("failed to generate signer key");
        assert!(status.success(), "failed to generate signer key");

        let status = Command::new("openssl")
            .args(["req", "-new", "-key"])
            .arg(&signer_key_path)
            .args(["-out"])
            .arg(&signer_csr_path)
            .args(["-subj", "/CN=Test Signer"])
            .status()
            .expect("failed to generate signer csr");
        assert!(status.success(), "failed to generate signer csr");

        let status = Command::new("openssl")
            .args(["x509", "-req", "-in"])
            .arg(&signer_csr_path)
            .args(["-CA"])
            .arg(&root_cert_path)
            .args(["-CAkey"])
            .arg(&root_key_path)
            .args(["-CAcreateserial", "-out"])
            .arg(&signer_cert_path)
            .args(["-days", "365"])
            .args(["-extfile"])
            .arg(&ee_ext_path)
            .status()
            .expect("failed to generate signer cert");
        assert!(status.success(), "failed to generate signer cert");

        let other_root_key_path = dir.join("other_root.key");
        let other_root_cert_path = dir.join("other_root.crt");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&other_root_key_path)
            .status()
            .expect("failed to generate other root key");
        assert!(status.success(), "failed to generate other root key");

        let status = Command::new("openssl")
            .args(["req", "-x509", "-new", "-key"])
            .arg(&other_root_key_path)
            .args(["-out"])
            .arg(&other_root_cert_path)
            .args(["-days", "3650", "-subj", "/CN=Other Root CA"])
            .args(["-addext", "basicConstraints=critical,CA:TRUE"])
            .args(["-addext", "keyUsage=keyCertSign,cRLSign"])
            .status()
            .expect("failed to generate other root cert");
        assert!(status.success(), "failed to generate other root cert");

        let root_cert_pem = std::fs::read(&root_cert_path).expect("failed to read root cert");
        let signer_cert_pem = std::fs::read(&signer_cert_path).expect("failed to read signer cert");
        let signer_key_pem = std::fs::read(&signer_key_path).expect("failed to read signer key");
        let other_root_cert_pem =
            std::fs::read(&other_root_cert_path).expect("failed to read other root cert");

        Self {
            root_cert_pem,
            signer_cert_pem,
            signer_key_pem,
            other_root_cert_pem,
            temp_dir,
        }
    }

    fn openssl_sign(&self, data: &[u8], extra_args: &[&str]) -> Vec<u8> {
        let dir = self.temp_dir.path();
        let data_path = dir.join("openssl-input.bin");
        let signer_cert_path = dir.join("openssl-signer.crt");
        let signer_key_path = dir.join("openssl-signer.key");
        let signature_path = dir.join("openssl-signature.cms");
        std::fs::write(&data_path, data).expect("failed to write OpenSSL input");
        std::fs::write(&signer_cert_path, &self.signer_cert_pem)
            .expect("failed to write OpenSSL signer certificate");
        std::fs::write(&signer_key_path, &self.signer_key_pem)
            .expect("failed to write OpenSSL signer key");
        let status = Command::new("openssl")
            .args(["cms", "-sign", "-in"])
            .arg(&data_path)
            .args(["-signer"])
            .arg(&signer_cert_path)
            .args(["-inkey"])
            .arg(&signer_key_path)
            .args(["-out"])
            .arg(&signature_path)
            .args(["-outform", "DER", "-nodetach", "-binary"])
            .args(extra_args)
            .status()
            .expect("failed to run OpenSSL CMS signing");
        assert!(status.success(), "OpenSSL CMS signing failed");
        std::fs::read(signature_path).expect("failed to read OpenSSL signature")
    }
}

#[test]
fn test_verification_accepts_rotated_roots_in_either_order() {
    let pki = TestPki::new();
    let signature = CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem)
        .unwrap()
        .sign(b"root rotation")
        .unwrap();

    for roots in [
        [&pki.other_root_cert_pem, &pki.root_cert_pem],
        [&pki.root_cert_pem, &pki.other_root_cert_pem],
    ] {
        let verifiers: Vec<_> = roots
            .iter()
            .map(|root| CmsVerifier::new(root).unwrap())
            .collect();
        assert_eq!(
            CmsVerifier::verify_with_any_root(&signature, &verifiers)
                .unwrap()
                .content,
            b"root rotation"
        );
    }
}

