#[test]
fn test_later_signer_info_is_tried_after_an_invalid_one() {
    let pki = TestPki::new();
    let signature = CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem)
        .unwrap()
        .sign(b"multiple signer infos")
        .unwrap();
    let mut content_info = ContentInfo::from_der(&signature).unwrap();
    let mut signed_data = content_info.content.decode_as::<SignedData>().unwrap();
    let mut invalid = signed_data.signer_infos.0.iter().next().unwrap().clone();
    invalid.signature = OctetString::new(vec![0; invalid.signature.as_bytes().len()]).unwrap();
    signed_data.signer_infos.0.insert(invalid).unwrap();
    assert_eq!(signed_data.signer_infos.0.len(), 2);
    content_info.content = Any::from_der(&signed_data.to_der().unwrap()).unwrap();

    let result = CmsVerifier::new(&pki.root_cert_pem)
        .unwrap()
        .verify(&content_info.to_der().unwrap())
        .unwrap();
    assert_eq!(result.content, b"multiple signer infos");
}

#[test]
fn test_sign_and_verify() {
    let pki = TestPki::new();
    let data = b"Hello, World!";

    let signer =
        CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem).expect("failed to create signer");
    let signature = signer.sign(data).expect("failed to sign");

    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    let result = verifier.verify(&signature).expect("failed to verify");
    assert_eq!(result.content, data);

    let signing_time = result.signing_time.expect("signing time should be present");
    let elapsed = SystemTime::now()
        .duration_since(signing_time)
        .expect("signing time should be in the past");
    assert!(
        elapsed < Duration::from_secs(60),
        "signing time should be recent, got {:?} ago",
        elapsed
    );
}

#[test]
fn test_verify_wrong_root() {
    let pki = TestPki::new();
    let data = b"Hello, World!";

    let signer =
        CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem).expect("failed to create signer");
    let signature = signer.sign(data).expect("failed to sign");

    let verifier = CmsVerifier::new(&pki.other_root_cert_pem)
        .expect("failed to create verifier with wrong root");
    let result = verifier.verify(&signature);
    assert!(result.is_err(), "verification should fail with wrong root");
}

#[test]
fn test_verify_content() {
    let pki = TestPki::new();
    let data = b"Hello, World!";

    let signer =
        CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem).expect("failed to create signer");
    let signature = signer.sign(data).expect("failed to sign");

    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    verifier
        .verify_content(&signature, data)
        .expect("verify_content should succeed");

    let result = verifier.verify_content(&signature, b"wrong data");
    assert!(
        result.is_err(),
        "verify_content should fail with wrong data"
    );
}

#[test]
fn test_openssl_interop_verify_our_signature() {
    let pki = TestPki::new();
    let dir = pki.temp_dir.path();
    let data = b"Hello from Rust!";

    let signer =
        CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem).expect("failed to create signer");
    let signature = signer.sign(data).expect("failed to sign");

    let sig_path = dir.join("signature.cms");
    std::fs::write(&sig_path, &signature).expect("failed to write signature");

    let root_path = dir.join("root.crt");
    std::fs::write(&root_path, &pki.root_cert_pem).expect("failed to write root cert");

    let output_path = dir.join("output.bin");
    let status = Command::new("openssl")
        .args(["cms", "-verify", "-in"])
        .arg(&sig_path)
        .args(["-inform", "DER", "-out"])
        .arg(&output_path)
        .args([
            "-no-CAfile",
            "-no-CApath",
            "-no-CAstore",
            "-verify_retcode",
            "-CAfile",
        ])
        .arg(&root_path)
        .status()
        .expect("failed to run openssl verify");

    assert!(
        status.success(),
        "OpenSSL should successfully verify our signature"
    );

    let extracted = std::fs::read(&output_path).expect("failed to read output");
    assert_eq!(extracted, data, "extracted content should match");
}

#[test]
fn test_openssl_interop_sign_with_openssl() {
    let pki = TestPki::new();
    let dir = pki.temp_dir.path();
    let data = b"Hello from OpenSSL!";

    let data_path = dir.join("data.bin");
    std::fs::write(&data_path, data).expect("failed to write data");

    let root_path = dir.join("root.crt");
    std::fs::write(&root_path, &pki.root_cert_pem).expect("failed to write root cert");

    let signer_cert_path = dir.join("signer.crt");
    std::fs::write(&signer_cert_path, &pki.signer_cert_pem).expect("failed to write signer cert");

    let signer_key_path = dir.join("signer.key");
    std::fs::write(&signer_key_path, &pki.signer_key_pem).expect("failed to write signer key");

    let sig_path = dir.join("signature.cms");
    let status = Command::new("openssl")
        .args(["cms", "-sign", "-in"])
        .arg(&data_path)
        .args(["-signer"])
        .arg(&signer_cert_path)
        .args(["-inkey"])
        .arg(&signer_key_path)
        .args(["-out"])
        .arg(&sig_path)
        .args(["-outform", "DER", "-nosmimecap", "-nodetach", "-binary"])
        .status()
        .expect("failed to run openssl sign");

    assert!(
        status.success(),
        "OpenSSL should successfully sign the data"
    );

    let signature = std::fs::read(&sig_path).expect("failed to read signature");
    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    let result = verifier
        .verify(&signature)
        .expect("failed to verify OpenSSL signature");
    assert_eq!(result.content, data, "content should match");
}

