/// Test PKI with intermediate certificate.
struct TestPkiWithIntermediate {
    root_cert_pem: Vec<u8>,
    intermediate_cert_pem: Vec<u8>,
    signer_cert_pem: Vec<u8>,
    signer_key_pem: Vec<u8>,
    #[allow(dead_code)]
    temp_dir: tempfile::TempDir,
}

impl TestPkiWithIntermediate {
    fn new() -> Self {
        let temp_dir = tempfile::tempdir().expect("failed to create temp dir");
        let dir = temp_dir.path();

        let ee_ext_path = dir.join("ee.ext");
        std::fs::write(
            &ee_ext_path,
            "basicConstraints=critical,CA:FALSE\nkeyUsage=digitalSignature\n",
        )
        .expect("failed to write EE extensions");

        let root_key_path = dir.join("root.key");
        let root_cert_path = dir.join("root.crt");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&root_key_path)
            .status()
            .expect("failed to generate root key");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["req", "-x509", "-new", "-key"])
            .arg(&root_key_path)
            .args(["-out"])
            .arg(&root_cert_path)
            .args(["-days", "3650", "-subj", "/CN=Test Root CA"])
            .args(["-addext", "basicConstraints=critical,CA:TRUE"])
            .args(["-addext", "keyUsage=keyCertSign,cRLSign"])
            .status()
            .expect("failed to generate root cert");
        assert!(status.success());

        let intermediate_key_path = dir.join("intermediate.key");
        let intermediate_csr_path = dir.join("intermediate.csr");
        let intermediate_cert_path = dir.join("intermediate.crt");
        let intermediate_ext_path = dir.join("intermediate.ext");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&intermediate_key_path)
            .status()
            .expect("failed to generate intermediate key");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["req", "-new", "-key"])
            .arg(&intermediate_key_path)
            .args(["-out"])
            .arg(&intermediate_csr_path)
            .args(["-subj", "/CN=Test Intermediate CA"])
            .status()
            .expect("failed to generate intermediate csr");
        assert!(status.success());

        std::fs::write(
            &intermediate_ext_path,
            "[v3_ca]\n\
basicConstraints = CA:TRUE\n\
keyUsage = keyCertSign, cRLSign\n",
        )
        .expect("failed to write intermediate extensions");

        let status = Command::new("openssl")
            .args(["x509", "-req", "-in"])
            .arg(&intermediate_csr_path)
            .args(["-CA"])
            .arg(&root_cert_path)
            .args(["-CAkey"])
            .arg(&root_key_path)
            .args(["-CAcreateserial", "-out"])
            .arg(&intermediate_cert_path)
            .args(["-extfile"])
            .arg(&intermediate_ext_path)
            .args(["-extensions", "v3_ca"])
            .args(["-days", "1825"])
            .status()
            .expect("failed to generate intermediate cert");
        assert!(status.success());

        let signer_key_path = dir.join("signer.key");
        let signer_csr_path = dir.join("signer.csr");
        let signer_cert_path = dir.join("signer.crt");

        let status = Command::new("openssl")
            .args([
                "ecparam",
                "-name",
                "prime256v1",
                "-genkey",
                "-noout",
                "-out",
            ])
            .arg(&signer_key_path)
            .status()
            .expect("failed to generate signer key");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["req", "-new", "-key"])
            .arg(&signer_key_path)
            .args(["-out"])
            .arg(&signer_csr_path)
            .args(["-subj", "/CN=Test Signer"])
            .status()
            .expect("failed to generate signer csr");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["x509", "-req", "-in"])
            .arg(&signer_csr_path)
            .args(["-CA"])
            .arg(&intermediate_cert_path)
            .args(["-CAkey"])
            .arg(&intermediate_key_path)
            .args(["-CAcreateserial", "-out"])
            .arg(&signer_cert_path)
            .args(["-days", "365"])
            .args(["-extfile"])
            .arg(&ee_ext_path)
            .status()
            .expect("failed to generate signer cert");
        assert!(status.success());

        let root_cert_pem = std::fs::read(&root_cert_path).expect("failed to read root cert");
        let intermediate_cert_pem =
            std::fs::read(&intermediate_cert_path).expect("failed to read intermediate cert");
        let signer_cert_pem = std::fs::read(&signer_cert_path).expect("failed to read signer cert");
        let signer_key_pem = std::fs::read(&signer_key_path).expect("failed to read signer key");

        Self {
            root_cert_pem,
            intermediate_cert_pem,
            signer_cert_pem,
            signer_key_pem,
            temp_dir,
        }
    }
}

#[test]
fn test_certificate_chain_with_intermediate() {
    let pki = TestPkiWithIntermediate::new();
    let data = b"Data signed with intermediate cert chain";

    let signer = CmsSignerBuilder::new(&pki.signer_cert_pem, &pki.signer_key_pem)
        .expect("failed to create builder")
        .with_intermediate_cert(&pki.intermediate_cert_pem)
        .expect("failed to add intermediate cert")
        .build()
        .expect("failed to build signer");
    let signature = signer.sign(data).expect("failed to sign");

    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    let result = verifier.verify(&signature).expect("failed to verify");
    assert_eq!(result.content, data);
    assert_eq!(
        result.certificate_chain.len(),
        3,
        "chain should have 3 certs"
    );
}

/// PSS signature parameters decoded to vary only optional hash NULL encodings.
#[derive(Clone, der::Sequence)]
struct TestPssParams {
    #[asn1(context_specific = "0", tag_mode = "EXPLICIT", optional = "true")]
    hash: Option<spki::AlgorithmIdentifierOwned>,
    #[asn1(context_specific = "1", tag_mode = "EXPLICIT", optional = "true")]
    mgf: Option<spki::AlgorithmIdentifierOwned>,
    #[asn1(context_specific = "2", tag_mode = "EXPLICIT", optional = "true")]
    salt: Option<u8>,
    #[asn1(context_specific = "3", tag_mode = "EXPLICIT", optional = "true")]
    trailer: Option<u8>,
}

/// Omit optional hash NULLs without changing the signed attributes or signature.
fn omit_pss_hash_nulls(signature: &[u8]) -> Vec<u8> {
    let mut ci = ContentInfo::from_der(signature).unwrap();
    let mut sd = ci.content.decode_as::<SignedData>().unwrap();
    let mut si = sd.signer_infos.0.iter().next().unwrap().clone();
    let mut pss = si
        .signature_algorithm
        .parameters
        .as_ref()
        .unwrap()
        .decode_as::<TestPssParams>()
        .unwrap();
    pss.hash.as_mut().unwrap().parameters = None;
    let mgf = pss.mgf.as_mut().unwrap();
    let mut hash = mgf
        .parameters
        .as_ref()
        .unwrap()
        .decode_as::<spki::AlgorithmIdentifierOwned>()
        .unwrap();
    hash.parameters = None;
    mgf.parameters = Some(Any::encode_from(&hash).unwrap());
    si.signature_algorithm.parameters = Some(Any::encode_from(&pss).unwrap());
    sd.signer_infos.0 = [si].try_into().unwrap();
    ci.content = Any::encode_from(&sd).unwrap();
    ci.to_der().unwrap()
}

/// Test PKI with RSA keys for RSA-PSS testing.
struct TestPkiRsa {
    root_cert_pem: Vec<u8>,
    signer_cert_pem: Vec<u8>,
    signer_key_pem: Vec<u8>,
    #[allow(dead_code)]
    temp_dir: tempfile::TempDir,
}

impl TestPkiRsa {
    fn new() -> Self {
        let temp_dir = tempfile::tempdir().expect("failed to create temp dir");
        let dir = temp_dir.path();

        let ee_ext_path = dir.join("ee.ext");
        std::fs::write(
            &ee_ext_path,
            "basicConstraints=critical,CA:FALSE\nkeyUsage=digitalSignature\n",
        )
        .expect("failed to write EE extensions");

        let root_key_path = dir.join("root.key");
        let root_cert_path = dir.join("root.crt");

        let status = Command::new("openssl")
            .args(["genrsa", "-out"])
            .arg(&root_key_path)
            .args(["2048"])
            .status()
            .expect("failed to generate RSA root key");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["req", "-x509", "-new", "-key"])
            .arg(&root_key_path)
            .args(["-out"])
            .arg(&root_cert_path)
            .args(["-days", "3650", "-subj", "/CN=Test RSA Root CA"])
            .args(["-addext", "basicConstraints=critical,CA:TRUE"])
            .args(["-addext", "keyUsage=keyCertSign,cRLSign"])
            .status()
            .expect("failed to generate RSA root cert");
        assert!(status.success());

        let signer_key_path = dir.join("signer.key");
        let signer_csr_path = dir.join("signer.csr");
        let signer_cert_path = dir.join("signer.crt");

        let status = Command::new("openssl")
            .args(["genrsa", "-out"])
            .arg(&signer_key_path)
            .args(["2048"])
            .status()
            .expect("failed to generate RSA signer key");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["req", "-new", "-key"])
            .arg(&signer_key_path)
            .args(["-out"])
            .arg(&signer_csr_path)
            .args(["-subj", "/CN=Test RSA Signer"])
            .status()
            .expect("failed to generate RSA signer csr");
        assert!(status.success());

        let status = Command::new("openssl")
            .args(["x509", "-req", "-in"])
            .arg(&signer_csr_path)
            .args(["-CA"])
            .arg(&root_cert_path)
            .args(["-CAkey"])
            .arg(&root_key_path)
            .args(["-CAcreateserial", "-out"])
            .arg(&signer_cert_path)
            .args(["-days", "365"])
            .args(["-extfile"])
            .arg(&ee_ext_path)
            .status()
            .expect("failed to generate RSA signer cert");
        assert!(status.success());

        let root_cert_pem = std::fs::read(&root_cert_path).expect("failed to read root cert");
        let signer_cert_pem = std::fs::read(&signer_cert_path).expect("failed to read signer cert");
        let signer_key_pem = std::fs::read(&signer_key_path).expect("failed to read signer key");

        Self {
            root_cert_pem,
            signer_cert_pem,
            signer_key_pem,
            temp_dir,
        }
    }
    fn openssl_sign(&self, data: &[u8], extra_args: &[&str]) -> Vec<u8> {
        let dir = self.temp_dir.path();
        let data_path = dir.join("openssl-input.bin");
        let signer_cert_path = dir.join("openssl-signer.crt");
        let signer_key_path = dir.join("openssl-signer.key");
        let signature_path = dir.join("openssl-signature.cms");
        std::fs::write(&data_path, data).expect("failed to write OpenSSL input");
        std::fs::write(&signer_cert_path, &self.signer_cert_pem)
            .expect("failed to write OpenSSL signer certificate");
        std::fs::write(&signer_key_path, &self.signer_key_pem)
            .expect("failed to write OpenSSL signer key");
        let status = Command::new("openssl")
            .args(["cms", "-sign", "-in"])
            .arg(&data_path)
            .args(["-signer"])
            .arg(&signer_cert_path)
            .args(["-inkey"])
            .arg(&signer_key_path)
            .args(["-out"])
            .arg(&signature_path)
            .args(["-outform", "DER", "-nodetach", "-binary"])
            .args(extra_args)
            .status()
            .expect("failed to run OpenSSL CMS signing");
        assert!(status.success(), "OpenSSL CMS signing failed");
        std::fs::read(signature_path).expect("failed to read OpenSSL signature")
    }
}

#[test]
fn test_rsa_pss_sign_and_verify() {
    let pki = TestPkiRsa::new();
    let data = b"RSA-PSS signed data";

    let signer = CmsSignerBuilder::new(&pki.signer_cert_pem, &pki.signer_key_pem)
        .expect("failed to create builder")
        .with_rsa_mode(RsaSignatureMode::Pss)
        .with_rsa_hash(RsaHashAlgorithm::Sha256)
        .build()
        .expect("failed to build signer");
    assert_eq!(
        signer.algorithm(),
        rugix_pki::SignatureAlgorithm::RsaPssSha256
    );

    let signature = signer.sign(data).expect("failed to sign with RSA-PSS");
    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    let result = verifier
        .verify(&signature)
        .expect("failed to verify RSA-PSS signature");
    assert_eq!(result.content, data);
}

