#[test]
fn test_ed25519_large_data() {
    let pki = TestPkiEd25519::new();
    let data: Vec<u8> = (0..1024 * 1024).map(|i| (i % 256) as u8).collect();

    let signer =
        CmsSigner::new(&pki.signer_cert_pem, &pki.signer_key_pem).expect("failed to create signer");
    let signature = signer
        .sign(&data)
        .expect("failed to sign large data with Ed25519");

    let verifier = CmsVerifier::new(&pki.root_cert_pem).expect("failed to create verifier");
    let result = verifier
        .verify(&signature)
        .expect("failed to verify large Ed25519 signature");
    assert_eq!(result.content, data);
}

/// Inspection preserves metadata from a cryptographically invalid signature and excludes
/// intermediates.
#[test]
fn inspect_cms_does_not_verify_signatures_or_include_intermediate_subjects() {
    let pki = TestPki::new();
    let signer = CmsSignerBuilder::new(&pki.signer_cert_pem, &pki.signer_key_pem)
        .unwrap()
        .with_intermediate_cert(&pki.root_cert_pem)
        .unwrap()
        .build()
        .unwrap();
    let mut signature = signer.sign(b"inspection content").unwrap();
    let verifier = CmsVerifier::new(&pki.root_cert_pem).unwrap();
    verifier.verify(&signature).unwrap();
    *signature.last_mut().unwrap() ^= 1;
    assert!(verifier.verify(&signature).is_err());
    let inspection = rugix_pki::inspect_cms(&signature).unwrap();
    assert_eq!(
        inspection.content.as_deref(),
        Some(b"inspection content".as_slice())
    );
    assert_eq!(inspection.signer_subjects, vec!["CN=Test Signer"]);
    assert!(inspection.errors.is_empty());
}

/// OpenSSL RSA CMS encodings work for all supported hashes, with and without attributes.
#[test]
fn test_openssl_rsa_cms_encodings() {
    let pki = TestPkiRsa::new();
    let verifier = CmsVerifier::new(&pki.root_cert_pem).unwrap();
    for hash in ["sha256", "sha384", "sha512"] {
        for pss in [false, true] {
            for noattr in [false, true] {
                let mut args = vec!["-md", hash];
                if pss {
                    args.extend([
                        "-keyopt",
                        "rsa_padding_mode:pss",
                        "-keyopt",
                        "rsa_pss_saltlen:digest",
                    ]);
                }
                if noattr {
                    args.push("-noattr");
                }
                let signature = pki.openssl_sign(b"OpenSSL RSA CMS", &args);
                if pss {
                    let absent_nulls = omit_pss_hash_nulls(&signature);
                    verifier
                        .verify_content(&absent_nulls, b"OpenSSL RSA CMS")
                        .unwrap();
                    assert_eq!(
                        verify_cms_with_certificate(&absent_nulls, &pki.signer_cert_pem).unwrap(),
                        b"OpenSSL RSA CMS"
                    );
                }

                assert_eq!(
                    verify_cms_with_certificate(&signature, &pki.signer_cert_pem).unwrap(),
                    b"OpenSSL RSA CMS"
                );
                assert!(verify_cms_with_certificate(&signature, &pki.root_cert_pem).is_err());
                let result = verifier.verify(&signature);
                assert!(
                    result.is_ok(),
                    "{hash} pss={pss} noattr={noattr}: {result:?}"
                );
                verifier
                    .verify_content(&signature, b"OpenSSL RSA CMS")
                    .unwrap();
                assert!(verifier.verify_content(&signature, b"tampered").is_err());
            }
        }
    }
}

/// Both policies reject tampering, inconsistent or unsupported digests, and malformed
/// parameters.
#[test]
fn test_openssl_rsa_cms_rejections() {
    let pki = TestPkiRsa::new();
    let verifier = CmsVerifier::new(&pki.root_cert_pem).unwrap();
    for extra in [
        vec![],
        vec![
            "-keyopt",
            "rsa_padding_mode:pss",
            "-keyopt",
            "rsa_pss_saltlen:digest",
        ],
    ] {
        for noattr in [false, true] {
            let mut args = vec!["-md", "sha256"];
            args.extend(extra.iter().copied());
            if noattr {
                args.push("-noattr");
            }
            let original = pki.openssl_sign(b"original", &args);
            for mutation in 0..6 {
                let mut ci = ContentInfo::from_der(&original).unwrap();
                let mut sd = ci.content.decode_as::<SignedData>().unwrap();
                let mut si = sd.signer_infos.0.iter().next().unwrap().clone();
                match mutation {
                    0 => {
                        sd.encap_content_info.econtent = Some(
                            Any::encode_from(&OctetString::new(b"modified".to_vec()).unwrap())
                                .unwrap(),
                        )
                    }
                    1 => {
                        si.signature =
                            OctetString::new(vec![0; si.signature.as_bytes().len()]).unwrap()
                    }
                    2 | 3 => {
                        si.digest_alg.oid =
                            const_oid::ObjectIdentifier::new_unwrap(if mutation == 2 {
                                "2.16.840.1.101.3.4.2.2"
                            } else {
                                "1.3.14.3.2.26"
                            });
                        sd.digest_algorithms = [si.digest_alg.clone()].try_into().unwrap();
                    }
                    4 => {
                        si.signature_algorithm.parameters =
                            Some(Any::encode_from(&OctetString::new(vec![1]).unwrap()).unwrap())
                    }
                    5 => si.signature_algorithm.parameters = None,
                    _ => unreachable!(),
                }
                sd.signer_infos.0 = [si].try_into().unwrap();
                ci.content = Any::encode_from(&sd).unwrap();
                let modified = ci.to_der().unwrap();
                assert!(verifier.verify(&modified).is_err(), "mutation={mutation}");
                assert!(
                    verify_cms_with_certificate(&modified, &pki.signer_cert_pem).is_err(),
                    "mutation={mutation}"
                );
            }
        }
    }
}

/// OpenSSL signatures outside the supported PSS profile remain rejected.
#[test]
fn test_openssl_rsa_pss_unsupported_parameters() {
    let pki = TestPkiRsa::new();
    let verifier = CmsVerifier::new(&pki.root_cert_pem).unwrap();
    for options in [
        vec!["-md", "sha1", "-keyopt", "rsa_pss_saltlen:digest"],
        vec!["-md", "sha256", "-keyopt", "rsa_pss_saltlen:20"],
        vec![
            "-md",
            "sha256",
            "-keyopt",
            "rsa_pss_saltlen:digest",
            "-keyopt",
            "rsa_mgf1_md:sha384",
        ],
    ] {
        let mut args = vec!["-keyopt", "rsa_padding_mode:pss"];
        args.extend(options);
        let signature = pki.openssl_sign(b"unsupported PSS", &args);
        assert!(verifier.verify(&signature).is_err());
        assert!(verify_cms_with_certificate(&signature, &pki.signer_cert_pem).is_err());
    }
}
